    g.strokeStyle = '#1b1b24'; g.lineWidth = 3; g.beginPath(); g.moveTo(10, -36); g.lineTo(196, -36); g.stroke();
    poly(g, [[38, -62], [46, -84], [88, -84], [88, -62]], GLASS, '#0b0b10', 2.5);
