    g.beginPath(); g.moveTo(0, 0); g.quadraticCurveTo(-22, 6, -16, 36); g.quadraticCurveTo(0, 42, 12, 20); g.quadraticCurveTo(14, 6, 0, 0);
    g.fillStyle = ear; g.fill(); g.lineWidth = 3; g.strokeStyle = '#1b1b24'; g.stroke();
    g.restore();
    // collar + tag
